import "server-only";

import fs from "node:fs";
import path from "node:path";
import type {
  CandidateProfile,
  LlmEvidenceArtifact,
  LlmRelation,
  Paper,
  ProfilesArtifact,
} from "./types";

// The app reads exactly one data file: the public demo dataset. It is
// committed, carries no abstracts and no paper reserved for evaluation, and is
// generated by the project's private, deterministic pipeline. This loader
// reads it as written; it never recomputes or repairs it.

const SCHEMA = "vectorank.public_demo.v1";
const ARTIFACT_PATH = path.join(
  process.cwd(),
  "data",
  "demo",
  "vectorank_demo_v1.json",
);

let artifactCache: ProfilesArtifact | null = null;
let byIdCache: Map<string, CandidateProfile> | null = null;
let papersCache: Map<string, Paper> | null = null;

export function loadProfiles(): ProfilesArtifact {
  if (!artifactCache) {
    if (!fs.existsSync(ARTIFACT_PATH)) {
      throw new Error(
        `Missing ${path.relative(process.cwd(), ARTIFACT_PATH)}. It is committed; restore it from git.`,
      );
    }
    const artifact = JSON.parse(
      fs.readFileSync(ARTIFACT_PATH, "utf8"),
    ) as ProfilesArtifact;
    if (artifact.schema !== SCHEMA) {
      throw new Error(
        `Unexpected artifact schema "${artifact.schema}"; this UI reads ${SCHEMA}.`,
      );
    }
    // AI-discovered profiles (separate, offline-generated file) join the list so
    // search and routes resolve them like any other candidate; they keep their
    // own `discovery` marker and `source` on every relation.
    const known = new Set(artifact.profiles.map((p) => p.candidate_id));
    const discovered = (loadLlmEvidence()?.discovered_profiles ?? []).filter(
      (p) => !known.has(p.candidate_id),
    );
    if (discovered.length > 0) {
      artifact.profiles = [...artifact.profiles, ...discovered];
      artifact.counts = {
        ...artifact.counts,
        candidate_profiles: artifact.profiles.length,
        ai_discovered_profiles: discovered.length,
      };
    }
    artifactCache = artifact;
    byIdCache = new Map(artifact.profiles.map((p) => [p.candidate_id, p]));
    papersCache = new Map(Object.entries(artifact.papers));
  }
  return artifactCache;
}

export function getProfile(candidateId: string): CandidateProfile | undefined {
  loadProfiles();
  return byIdCache!.get(candidateId);
}

// Bibliographic metadata is the PubMed record (title, journal, year), checked
// against the corpus title at build time. Only papers with displayed evidence
// are present.
export function loadPapers(): Map<string, Paper> {
  loadProfiles();
  return papersCache!;
}

// AI-extracted evidence is an optional second file, generated offline. The app
// never calls a model while browsing; when the file is absent nothing is shown.
const LLM_SCHEMA = "vectorank.public_llm_evidence.v1";
const LLM_PATH = path.join(
  process.cwd(),
  "data",
  "demo",
  "vectorank_llm_evidence_v1.json",
);
let llmCache: LlmEvidenceArtifact | null | undefined;

export function loadLlmEvidence(): LlmEvidenceArtifact | null {
  if (llmCache === undefined) {
    llmCache = null;
    if (fs.existsSync(LLM_PATH)) {
      const doc = JSON.parse(
        fs.readFileSync(LLM_PATH, "utf8"),
      ) as LlmEvidenceArtifact;
      if (doc.schema !== LLM_SCHEMA) {
        throw new Error(`Unexpected schema "${doc.schema}"; expected ${LLM_SCHEMA}.`);
      }
      llmCache = doc;
    }
  }
  return llmCache;
}

export function getLlmEvidence(candidateId: string): LlmRelation[] {
  return (
    loadLlmEvidence()?.relations.filter((r) => r.candidate_id === candidateId) ??
    []
  );
}
